<script setup lang="ts">
import FieldError from '../FleetAndDocuments/components/FieldError.vue';
import {computed,onMounted,onBeforeUnmount,ref,watch,useId} from 'vue';
import { useModuleRequests } from '../Office/useModuleRequests';
const {all,paginated,request}=useModuleRequests();
import {date,money,paymentLabels,type Invoice} from './contracts';
const props=defineProps<{locked:boolean;epoch:number;errors:Record<string,string[]>}>();const emit=defineEmits<{command:[title:string,path:string,body:Record<string,unknown>];error:[error:unknown]}>();
const rows=ref<Invoice[]>([]),customers=ref<{id:string;name:string}[]>([]),customer=ref(''),status=ref(''),from=ref(''),to=ref(''),search=ref(''),loading=ref(false),page=ref(1),last=ref(1),selected=ref<Invoice|null>(null),amount=ref(''),paidAt=ref(''),reason=ref(''),method=ref('');let generation=0;
const customerOptions=computed(()=>customers.value.filter(c=>c.name.toLocaleLowerCase('es').includes(search.value.toLocaleLowerCase('es'))));
async function load(target=1):Promise<void>{if(loading.value)return;const current=++generation;loading.value=true;try{const query=new URLSearchParams({page:String(target)});if(customer.value)query.set('customer_id',customer.value);if(status.value)query.set('status',status.value);if(from.value)query.set('from',from.value);if(to.value)query.set('to',to.value);const result=await paginated<Invoice>(`/billing/invoices?${query}`);if(current!==generation)return;rows.value=result.data;page.value=result.meta.current_page;last.value=result.meta.last_page;if(selected.value){const detail=await request<Invoice>(`/billing/invoices/${selected.value.id}`);if(current===generation)selected.value=detail;}}catch(e){if(current===generation)emit('error',e);}finally{if(current===generation)loading.value=false;}}
async function inspect(row:Invoice):Promise<void>{if(loading.value)return;const current=++generation;loading.value=true;try{const result=await request<Invoice>(`/billing/invoices/${row.id}`);if(current!==generation)return;selected.value=result;amount.value='';reason.value='';method.value='';paidAt.value='';}catch(e){if(current===generation)emit('error',e);}finally{if(current===generation)loading.value=false;}}
function pay():void{if(!selected.value||props.locked||loading.value)return;emit('command','Registrar pago administrativo',`/billing/invoices/${selected.value.id}/payments`,{amount:amount.value,currency:selected.value.currency,paid_at:`${paidAt.value}:00-06:00`,reason:reason.value,...(method.value.trim()?{method:method.value.trim()}:{})});}
watch(()=>props.epoch,()=>{amount.value='';paidAt.value='';reason.value='';method.value='';void load(page.value);});onMounted(async()=>{const current=generation;try{const data=await all<{id:string;name:string}>('/transport/lookups/customers');if(current!==generation)return;customers.value=data;await load();}catch(e){if(current===generation)emit('error',e);}});onBeforeUnmount(()=>generation++);
const errorId=useId();
</script>
<template><section class="space-y-4"><h2 class="text-xl font-semibold">Facturas administrativas y pagos</h2><form data-office-filter class="panel grid gap-3 md:grid-cols-3" @submit.prevent="load()"><label>Buscar cliente<input v-model="search" class="field" type="search" :disabled="locked||loading"></label><label>Cliente<select aria-label="Cliente" v-model="customer" class="field" :disabled="locked||loading"><option value="">Todos</option><option v-for="item in customerOptions" :key="item.id" :value="item.id">{{item.name}}</option></select></label><label>Estado de pago<select aria-label="Estado de pago" v-model="status" class="field" :disabled="locked||loading"><option value="">Todos</option><option v-for="(label,value) in paymentLabels" :key="value" :value="value">{{label}}</option></select></label><label>Registradas desde<input v-model="from" type="date" class="field" :disabled="locked||loading"></label><label>Registradas hasta<input v-model="to" type="date" class="field" :disabled="locked||loading"></label><button class="btn-primary" :disabled="locked||loading">Consultar facturas</button></form><p v-if="loading" role="status">Consultando facturas…</p><div class="overflow-x-auto"><table class="data-table"><thead><tr><th>Documento interno / cliente</th><th>Total</th><th>Pagado</th><th>Saldo</th><th>Estado</th><th>Consulta</th></tr></thead><tbody><tr v-for="row in rows" :key="row.id"><td>{{row.customer.name}}<br><span class="text-xs">{{row.id}}</span></td><td>{{money(row.total,row.currency)}}</td><td>{{money(row.paid,row.currency)}}</td><td>{{money(row.balance,row.currency)}}</td><td>{{paymentLabels[row.status]}}</td><td><button class="btn-secondary" :disabled="locked||loading" @click="inspect(row)">Ver factura y pagos</button></td></tr></tbody></table></div><p v-if="!loading&&!rows.length">No hay facturas para estos filtros.</p><div class="flex gap-3"><button class="btn-secondary" :disabled="locked||loading||page<=1" @click="load(page-1)">Anterior</button><span>Página {{page}} de {{last}}</span><button class="btn-secondary" :disabled="locked||loading||page>=last" @click="load(page+1)">Siguiente</button></div><section v-if="selected" class="panel space-y-4"><div class="flex justify-between gap-3"><h3 class="font-semibold">Factura administrativa interna</h3><button class="btn-secondary" :disabled="locked||loading" @click="selected=null">Cerrar detalle</button></div><p class="[overflow-wrap:anywhere]">{{selected.customer.name}} · {{selected.id}}</p><p>Creada {{date(selected.registered_at)}} · usuario {{selected.created_by_id}}</p><p class="[overflow-wrap:anywhere]">{{selected.reason}}</p><div class="grid gap-3 sm:grid-cols-3"><p>Total: <strong>{{money(selected.total,selected.currency)}}</strong></p><p>Pagado: <strong>{{money(selected.paid,selected.currency)}}</strong></p><p>Saldo pendiente: <strong>{{money(selected.balance,selected.currency)}}</strong></p></div><p>{{paymentLabels[selected.status]}}</p><div class="overflow-x-auto"><table class="data-table"><thead><tr><th>Concepto / viaje</th><th>Cantidad</th><th>Importe aprobado</th></tr></thead><tbody><tr v-for="item in selected.items" :key="item.id"><td>{{item.concept}}<br><span class="text-xs">{{item.trip_id}} · aprobación {{item.price_proposal_id}}</span></td><td>1</td><td>{{money(item.amount,selected.currency)}}</td></tr></tbody></table></div><form v-if="selected.status!=='paid'" class="grid gap-3 md:grid-cols-2" @submit.prevent="pay"><h4 class="md:col-span-2 font-semibold">Registrar pago parcial o total</h4><label>Importe del pago<input aria-label="Importe del pago" v-model="amount" class="field" inputmode="decimal" pattern="[0-9]+([.][0-9]{1,2})?" required :disabled="locked||loading" :aria-invalid="!!errors['amount']?.length" :aria-describedby="errors['amount']?.length ? `${errorId}-amount-error` : undefined"><button type="button" class="text-blue-700 underline" :disabled="locked||loading" @click="amount=selected.balance">Utilizar saldo completo</button></label><FieldError :id="`${errorId}-amount-error`" :errors="errors['amount']"/><label>Fecha y hora del pago · Costa Rica<input v-model="paidAt" type="datetime-local" class="field" required :disabled="locked||loading" :aria-invalid="!!errors['paid_at']?.length" :aria-describedby="errors['paid_at']?.length ? `${errorId}-paidAt-error` : undefined"></label><FieldError :id="`${errorId}-paidAt-error`" :errors="errors['paid_at']"/><label>Medio de pago · descripción opcional<input v-model="method" class="field" maxlength="255" :disabled="locked||loading" placeholder="Descripción administrativa" :aria-invalid="!!errors['method']?.length" :aria-describedby="errors['method']?.length ? `${errorId}-method-error` : undefined"></label><FieldError :id="`${errorId}-method-error`" :errors="errors['method']"/><label>Motivo o referencia administrativa<textarea v-model="reason" class="field" maxlength="2000" required :disabled="locked||loading" :aria-invalid="!!errors['reason']?.length" :aria-describedby="errors['reason']?.length ? `${errorId}-reason-error` : undefined"/></label><FieldError :id="`${errorId}-reason-error`" :errors="errors['reason']"/><button class="btn-primary" :disabled="locked||loading">Registrar pago</button><p class="text-sm">El servidor confirma saldo y moneda dentro de una transacción. No se permiten sobrepagos, anticipos ni conversiones.</p></form><h4 class="font-semibold">Historial de pagos</h4><ol class="space-y-3"><li v-for="payment in selected.payments" :key="payment.id" class="border border-blue-200 rounded p-3"><strong>{{money(payment.amount,payment.currency)}}</strong><p>{{date(payment.paid_at)}} · registrado {{date(payment.registered_at)}} · usuario {{payment.recorded_by_id}}</p><p>{{payment.reason}} {{payment.method?`· ${payment.method}`:''}}</p><span class="text-xs">{{payment.id}}</span></li></ol><p v-if="!selected.payments.length">No hay pagos registrados.</p></section></section></template>
